const deleteCacheMutation = trpc.viewer.calendars.deleteCache.useMutation({
  onSuccess: () => {
    showToast(t("cache_deleted_successfully"), "success");
    onSuccess?.();
  },
  onError: () => {
    showToast(t("error_deleting_cache"), "error");
  },
  async onSettled() {
    await utils.viewer.calendars.connectedCalendars.invalidate();
  },
});

if (!credential) {
  const { TRPCError } = await import("@trpc/server");
  throw new TRPCError({
    code: "NOT_FOUND",
    message: "Credential not found or access denied",
  });
}

const credentialIds = connectedCalendars.map((cal) => cal.credentialId);
const { FeaturesRepository } = await import("@calcom/features/flags/features.repository");
const isCalendarCacheEnabled = await new FeaturesRepository().checkIfFeatureIsEnabledGlobally(
  "calendar-cache"
);
const cacheRepository = new CalendarCacheRepository();
const cacheStatuses = isCalendarCacheEnabled
  ? await cacheRepository.getCacheStatusByCredentialIds(credentialIds)
  : [];
